{
  "гриб": "Amanita phalloides (бледная поганка, death cap)",
  "состав": [
    {
      "вещество": "α-аманитин (α-amanitin)",
      "содержание": "30–50 мг/кг (свежей массы)",
      "влияние": "Блокирует РНК-полимеразу II, вызывая тяжёлый некроз печени и почек, летальная доза для человека ≈ 2 мг/кг."
    },
    {
      "вещество": "β-аманитин (β-amanitin)",
      "содержание": "5–20 мг/кг (свежей массы)",
      "влияние": "Ингибирует РНК-полимеразу II и I, усиливает гепато- и нефротоксическое действие α-аманитина."
    },
    {
      "вещество": "γ-аманитин (γ-amanitin)",
      "содержание": "1–5 мг/кг (свежей массы)",
      "влияние": "Менее токсичный изомер аманитинов, также подавляет синтез РНК в гепатоцитах."
    },
    {
      "вещество": "α-фаллотоксин (α-phallotoxin / фаллоидин)",
      "содержание": "10–20 мг/кг (свежей массы)",
      "влияние": "Нарушает полимеризацию актеновых микрofilamentов, вызывает гемолиз эритроцитов и кардио-гепатотоксичность."
    },
    {
      "вещество": "β-фаллотоксин (β-phallotoxin / фаллоциантин)",
      "содержание": "5–10 мг/кг (свежей массы)",
      "влияние": "Диссоциирует актиновые филаменты, усиливает цитотоксическое действие на печень и сердце."
    },
    {
      "вещество": "Иботеновая кислота (ibotenic acid)",
      "содержание": "10–50 мг/кг (свежей массы)",
      "влияние": "Агонист глутаматных рецепторов, вызывает возбуждение ЦНС, галлюцинации и судороги (нейротоксическая фаза)."
    },
    {
      "вещество": "Мусцимол (muscimol)",
      "содержание": "неизвестно (следовые количества, значительно меньше, чем у Amanita muscaria)",
      "влияние": "Агонист GABA-A рецепторов, оказывает седативное и противосудорожное действие на ЦНС."
    },
    {
      "вещество": "Эрготионеин (ergothioneine)",
      "содержание": "0,02–0,05 % сухой массы",
      "влияние": "Антиоксидант, участвует в защите клеток от окислительного стресса; не ядовит для человека."
    },
    {
      "вещество": "Хитин (chitin)",
      "содержание": "≈ 10–12 % сухой массы",
      "влияние": "Структурный компонент клеточной стенки; для человека инертен, не переваривается."
    },
    {
      "вещество": "Белки (общие)",
      "содержание": "≈ 40–50 % сухой массы",
      "влияние": "Обеспечивают ферментативные функции гриба; для человека в основном неперевариваемы, но могут нести антипитативные свойства."
    }
  ]
}

